import type { Filters } from './filters';
import type { Dish } from './types';

const SPICE = ['Not spicy', 'Mildly spicy', 'Spicy', 'Very spicy'];

/** "Why it matches" is built from the real matched filters, not generated by an LLM, so it can't be wrong. */
export function whyItMatches(d: Dish, f: Filters): string {
  const parts: string[] = [];
  if (f.vegan) parts.push('Vegan');
  else if (f.vegetarian) parts.push('Vegetarian');
  if (f.minSpice !== null || f.maxSpice !== null) parts.push(SPICE[d.spice_level]);
  for (const a of f.excludeAllergens) parts.push(`No ${a}`);
  for (const t of f.tags) if (d.tags.includes(t)) parts.push(t.replace('-', ' ').replace(/^./, (c) => c.toUpperCase()));
  parts.push(`KES ${d.price}`);
  return parts.join(' · ');
}
